"use client";

import { useState } from "react";
import { Frame, Title, Badge } from "../ui";

const sessions = [{ time: "09:00 – 10:30", title: "Opening Plenary", speaker: "OAK Foundation Leadership", venue: "Main Hall A", type: "Plenary" }, { time: "11:00 – 12:30", title: "Building stronger partner ecosystems", speaker: "James Odhiambo · OAK Foundation", venue: "Breakout Room 1", type: "Workshop" }, { time: "14:00 – 15:30", title: "Zimbabwe programme exchange", speaker: "Awa Diallo · Partner Network", venue: "Main Hall A", type: "Breakout" }, { time: "18:30 – 20:30", title: "Welcome dinner", speaker: "All partners", venue: "The Terrace", type: "Social" }];
export default function ProgrammePage() { const [docs, setDocs] = useState(false); const [day, setDay] = useState("MON"); return <Frame role="OAK Staff"><main className="mx-auto max-w-5xl px-5 py-10"><Title eyebrow="The gathering" title="Programme" description="Three days of shared learning, honest exchange, and practical collaboration." /><div className="mb-6 flex rounded-xl bg-slate-200 p-1"><button onClick={() => setDocs(false)} className={`flex-1 rounded-lg py-3 text-sm font-bold ${!docs ? "bg-white shadow-sm" : "text-slate-500"}`}>Schedule</button><button onClick={() => setDocs(true)} className={`flex-1 rounded-lg py-3 text-sm font-bold ${docs ? "bg-white shadow-sm" : "text-slate-500"}`}>Docs</button></div>{!docs ? <><div className="mb-6 grid grid-cols-3 gap-2">{[["MON", "Day 1 · 9 Nov"], ["TUE", "Day 2 · 10 Nov"], ["WED", "Day 3 · 11 Nov"]].map(([key, label]) => <button key={key} onClick={() => setDay(key)} className={`rounded-xl px-3 py-3 text-left ${day === key ? "bg-[#0f172a] text-white" : "bg-white text-slate-500 ring-1 ring-slate-200"}`}><span className="block text-[10px] font-bold tracking-wider">{key}</span><span className="text-xs font-semibold">{label}</span></button>)}</div><div className="mb-5 flex gap-2 overflow-auto">{["All", "Plenary", "Breakout", "Workshop", "Social"].map((filter) => <button key={filter} className="whitespace-nowrap rounded-full bg-white px-4 py-2 text-xs font-bold text-slate-600 ring-1 ring-slate-200">{filter}</button>)}</div><div className="space-y-4">{sessions.map((session) => <article key={session.title} className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div className="flex flex-col gap-4 sm:flex-row sm:items-start"><div className="min-w-32 text-sm font-bold text-emerald-700">{session.time}</div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-lg font-bold">{session.title}</h2><Badge>{session.type}</Badge></div><p className="mt-2 text-sm text-slate-500">{session.speaker}</p><p className="mt-3 text-xs font-semibold text-slate-400">⌖ {session.venue}</p></div></div></article>)}</div></> : <Docs />}</main></Frame>; }
function Docs() { return <div className="grid gap-5 lg:grid-cols-2"><section className="rounded-2xl bg-white p-6 ring-1 ring-slate-200"><div className="flex items-center justify-between"><h2 className="font-bold">Session Notes</h2><button className="rounded-lg bg-slate-900 px-3 py-2 text-xs font-bold text-white">+ Add Note</button></div><div className="mt-6 space-y-5">{[["AM", "Alex Moyo", "The strongest partnerships make room for uncertainty and learning."], ["JO", "James Odhiambo", "Capture the local context before reaching for a global solution."]].map(([initials, name, note]) => <div key={name} className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-emerald-100 text-xs font-bold text-emerald-800">{initials}</span><div><p className="text-sm font-bold">{name}</p><p className="mt-1 text-sm leading-6 text-slate-500">{note}</p></div></div>)}</div></section><section className="space-y-5"><div className="rounded-2xl bg-[#182c53] p-6 text-white"><h2 className="font-bold">Key Takeaways</h2><ul className="mt-4 space-y-3 text-sm leading-6 text-white/75"><li>• Centre partner voice in programme design.</li><li>• Share practical tools across regions.</li><li>• Leave with one action to carry forward.</li></ul></div><div className="rounded-2xl bg-white p-6 ring-1 ring-slate-200"><h2 className="font-bold">Resources</h2><div className="mt-4 space-y-3 text-sm text-slate-600"><p>↓ Partner workbook <span className="float-right text-xs text-slate-400">PDF · 2.4 MB</span></p><p>↓ Contact directory <span className="float-right text-xs text-slate-400">XLSX · 180 KB</span></p><p>↓ Event photos <span className="float-right text-xs text-slate-400">ZIP · 24 MB</span></p></div></div></section></div>; }
